# Module-level constants required by test harness
_ENDPOINT = "/insights/{org-slug}/summary"
_METHOD = "get"
_TEST_DATA_FILE = "insights_org-slug_summary.json"
_here = Path(__file__).resolve().parent
_endpoint_data_path = _here / _TEST_DATA_FILE

# Initialize validator once per module as required
_VALIDATOR = SwaggerSchemaValidator("api.json")


def _extract_endpoint_cases(merged: Optional[Dict[str, Any]], fallback_path: Path) -> List[Dict[str, Any]]:
    """
    Extracts a list of test-case dictionaries from the merged endpoint data.
    Tolerates different container keys and falls back to loading a JSON list
    directly if the endpoint file is a list.
    """
    if isinstance(merged, dict):
        for key in ("cases", "entries", "tests", "items", "data"):
            val = merged.get(key)
            if isinstance(val, list):
                return [x for x in val if isinstance(x, dict)]

    # Fallback: attempt to read a list directly from the file (the prompt's example shows a top-level list)
    try:
        raw = json.loads(fallback_path.read_text(encoding="utf-8"))
        if isinstance(raw, list):
            return [x for x in raw if isinstance(x, dict)]
    except Exception:
        pass

    return []


def _build_headers_valid(get_config) -> Dict[str, str]:
    headers: Dict[str, str] = {"Accept": "application/json"}
    # Auth header name per spec examples
    token = str(get_config("auth.api_key_header", "") or "")
    # Always include the header for "valid" path; empty token will behave as missing/invalid in envs without credentials
    headers["Circle-Token"] = token
    return headers


def _build_headers_invalid() -> Dict[str, str]:
    return {
        "Accept": "application/json",
        "Circle-Token": "invalid-token",
    }


def _build_headers_missing() -> Dict[str, str]:
    return {
        "Accept": "application/json",
    }


def _encode_project_names(value: Any) -> Optional[str]:
    """
    Since the spec declares 'project-names' as an object in query, pass as JSON string if provided.
    """
    if value is None:
        return None
    try:
        return json.dumps(value)
    except Exception:
        # Fallback to string
        return str(value)


def _resolve_org_slug(entry: Dict[str, Any], get_config) -> Optional[str]:
    # Endpoint JSON values override config.yml
    slug = entry.get("org-slug")
    if slug:
        return str(slug)
    # Fallback to config
    cfg_slug = get_config("test_data.org-slug", "")
    if cfg_slug:
        return str(cfg_slug)
    return None


@pytest.mark.smoke
def test_insights_summary_smoke_success(api_client, get_config, merged_test_data):
    """
    Happy-path success cases using only required fields.
    - Required: path parameter org-slug
    - Optional query params are intentionally omitted
    """
    # Load merged data; tolerate top-level list via fallback
    merged = None
    try:
        merged = merged_test_data(_endpoint_data_path)
    except Exception:
        merged = None

    entries = _extract_endpoint_cases(merged, _endpoint_data_path)

    # Filter smoke cases: those that contain only required inputs
    smoke_candidates: List[Dict[str, Any]] = []
    for e in entries:
        # Consider optional fields as per spec
        has_optional = any(k in e for k in ("reporting-window", "project-names"))
        if not has_optional:
            smoke_candidates.append(e)

    # If no suitable smoke case present, build a minimal case from config
    if not smoke_candidates:
        cfg_org = get_config("test_data.org-slug", "")
        if not cfg_org:
            pytest.skip("No smoke test data available and test_data.org-slug not configured")
        smoke_candidates = [{"org-slug": cfg_org, "statusCode": 200, "scenario": "Smoke: only required path params"}]

    for case in smoke_candidates:
        org_slug = _resolve_org_slug(case, get_config)
        if not org_slug:
            pytest.skip("Missing org-slug in data and config fallback")

        # Encode slug: '/' may need escaping per spec
        encoded_slug = quote(str(org_slug), safe="")
        endpoint_path = _ENDPOINT.replace("{org-slug}", encoded_slug)

        headers = _build_headers_valid(get_config)

        resp = api_client.get(endpoint_path, headers=headers)

        expected_status = int(case.get("statusCode", 200))
        assert resp.status_code == expected_status, f"Expected {expected_status} but got {resp.status_code} for scenario: {case.get('scenario')}"

        # Validate response schema against OpenAPI for 200
        result = _VALIDATOR.validate_schema_by_response(_ENDPOINT, _METHOD, str(expected_status), resp)
        assert result.get("valid"), f"Schema validation failed for 200 response: {result}"


def test_insights_summary_success_with_optional_params(api_client, get_config, merged_test_data):
    """
    Success cases including optional query params 'reporting-window' and/or 'project-names'.
    Values from endpoint JSON override config.yml.
    """
    merged = None
    try:
        merged = merged_test_data(_endpoint_data_path)
    except Exception:
        merged = None

    entries = _extract_endpoint_cases(merged, _endpoint_data_path)

    opt_cases = [e for e in entries if any(k in e for k in ("reporting-window", "project-names"))]
    if not opt_cases:
        pytest.skip("No optional-parameter test entries present")

    for case in opt_cases:
        org_slug = _resolve_org_slug(case, get_config)
        if not org_slug:
            pytest.skip("Missing org-slug in data and config fallback")

        encoded_slug = quote(str(org_slug), safe="")
        endpoint_path = _ENDPOINT.replace("{org-slug}", encoded_slug)

        params: Dict[str, Any] = {}
        if "reporting-window" in case:
            params["reporting-window"] = str(case["reporting-window"])

        if "project-names" in case:
            pn = _encode_project_names(case.get("project-names"))
            if pn is not None:
                params["project-names"] = pn

        headers = _build_headers_valid(get_config)

        resp = api_client.get(endpoint_path, headers=headers, params=params)

        expected_status = int(case.get("statusCode", 200))
        assert resp.status_code == expected_status, (
            f"Expected {expected_status} but got {resp.status_code} "
            f"for optional-params scenario: {case.get('scenario')}"
        )

        result = _VALIDATOR.validate_schema_by_response(_ENDPOINT, _METHOD, str(expected_status), resp)
        assert result.get("valid"), f"Schema validation failed for {expected_status} response: {result}"


@pytest.mark.parametrize("auth_mode", ["invalid", "missing"])
def test_insights_summary_auth_errors(api_client, get_config, merged_test_data, auth_mode: str):
    """
    Negative tests for auth:
      - invalid token
      - missing token
    Validate against the 'default' error response schema.
    """
    merged = None
    try:
        merged = merged_test_data(_endpoint_data_path)
    except Exception:
        merged = None

    entries = _extract_endpoint_cases(merged, _endpoint_data_path)
    # Use first available org-slug or fallback to config
    base = entries[0] if entries else {}
    org_slug = _resolve_org_slug(base, get_config)
    if not org_slug:
        pytest.skip("No org-slug available for auth negative tests")

    encoded_slug = quote(str(org_slug), safe="")
    endpoint_path = _ENDPOINT.replace("{org-slug}", encoded_slug)

    headers = _build_headers_invalid() if auth_mode == "invalid" else _build_headers_missing()

    resp = api_client.get(endpoint_path, headers=headers)
    assert not (200 <= resp.status_code < 300), f"Expected non-2xx for {auth_mode} auth, got: {resp.status_code}"

    # Validate against 'default' error schema
    result = _VALIDATOR.validate_schema_by_response(_ENDPOINT, _METHOD, "default", resp)
    assert result.get("valid"), f"Default error schema validation failed: {result}"


